import React, { useState, useEffect } from 'react';
import { Shield, Users, Globe, Heart, Target, Award, Zap, Lock, ChevronDown, Play, Pause } from 'lucide-react';

interface ServiceCardProps {
  icon: React.ReactNode;
  title: string;
  description: string;
  delay: number;
}

interface ValueCardProps {
  icon: React.ReactNode;
  title: string;
  description: string;
  delay: number;
}

interface CounterProps {
  end: number;
  duration: number;
  suffix?: string;
}

const Counter: React.FC<CounterProps> = ({ end, duration, suffix = "" }) => {
  const [count, setCount] = useState(0);

  useEffect(() => {
    let startTime: number;
    let animationFrame: number;

    const animate = (currentTime: number) => {
      if (!startTime) startTime = currentTime;
      const progress = Math.min((currentTime - startTime) / duration, 1);
      
      setCount(Math.floor(progress * end));
      
      if (progress < 1) {
        animationFrame = requestAnimationFrame(animate);
      }
    };

    animationFrame = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationFrame);
  }, [end, duration]);

  return <span>{count}{suffix}</span>;
};

const ServiceCard: React.FC<ServiceCardProps> = ({ icon, title, description, delay }) => (
  <div 
    className="group bg-white/90 backdrop-blur-sm rounded-2xl shadow-xl p-8 hover:shadow-2xl transition-all duration-700 border border-white/20 hover:border-blue-300/50 hover:-translate-y-2 transform"
    style={{ animationDelay: `${delay}ms` }}
  >
    <div className="relative overflow-hidden rounded-xl mb-6 h-48 bg-gradient-to-br from-blue-500 to-purple-600">
      <div className="absolute inset-0 bg-black/20"></div>
      <div className="absolute top-4 left-4 p-3 bg-white/20 backdrop-blur-sm rounded-lg">
        {icon}
      </div>
      <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"></div>
      <div className="absolute bottom-4 left-4 text-white">
        <div className="w-16 h-1 bg-white/60 rounded-full mb-2 group-hover:w-24 transition-all duration-500"></div>
      </div>
    </div>
    <h3 className="text-2xl font-bold text-gray-800 mb-4 group-hover:text-blue-600 transition-colors duration-300">{title}</h3>
    <p className="text-gray-600 leading-relaxed group-hover:text-gray-700 transition-colors duration-300">{description}</p>
    <div className="mt-6 opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-y-2 group-hover:translate-y-0">
      <button className="bg-gradient-to-r from-blue-500 to-purple-600 text-white px-6 py-2 rounded-lg font-semibold hover:shadow-lg transition-shadow duration-300">
        Learn More
      </button>
    </div>
  </div>
);

const ValueCard: React.FC<ValueCardProps> = ({ icon, title, description, delay }) => (
  <div 
    className="group text-center p-8 bg-gradient-to-br from-white/80 to-blue-50/80 backdrop-blur-sm rounded-2xl hover:from-blue-50/90 hover:to-indigo-100/90 transition-all duration-700 border border-white/30 hover:border-blue-300/50 hover:scale-105 transform"
    style={{ animationDelay: `${delay}ms` }}
  >
    <div className="relative inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-blue-500 to-purple-600 rounded-full mb-6 group-hover:scale-110 transition-transform duration-500 shadow-lg">
      <div className="absolute inset-0 bg-gradient-to-br from-blue-400 to-purple-500 rounded-full animate-pulse opacity-75"></div>
      {React.cloneElement(icon as React.ReactElement, { className: "w-10 h-10 text-white relative z-10" })}
    </div>
    <h3 className="text-2xl font-bold text-gray-800 mb-4 group-hover:text-blue-600 transition-colors duration-300">{title}</h3>
    <p className="text-gray-600 group-hover:text-gray-700 transition-colors duration-300">{description}</p>
  </div>
);

